<template>
  <section class="ptw-section ptw-cutting" v-loading="loading">
    <div class="ptw-section-title"><h4>自主下料</h4><el-button size="mini" :disabled="busy || dirty" @click="load">刷新</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
    <div v-if="pending.length" class="ptw-pending"><el-alert title="原下料操作结果未确认，请保留原记录重试。" type="warning" :closable="false" /><el-button v-for="job in pending" :key="job.path" size="small" :loading="busy" @click="recover(job)">重试原操作</el-button></div>
    <template v-if="detail">
      <el-table v-if="componentMode" :data="detail.component_requirements || []" border size="mini" empty-text="暂无已冻结的下料明细"><el-table-column prop="raw_item_name" label="原材料" min-width="140" /><el-table-column label="下料要求" min-width="145"><template slot-scope="{row}">{{ requirementText(row) }}</template></el-table-column><el-table-column label="已确认" min-width="110"><template slot-scope="{row}">{{ totalLength(row) ? totalLengthMetres(row.confirmed_total_length_mm) + ' m' : row.confirmed_piece_qty + ' 件' }}</template></el-table-column><el-table-column label="剩余" min-width="110"><template slot-scope="{row}">{{ totalLength(row) ? totalLengthMetres(row.remaining_total_length_mm) + ' m' : row.remaining_piece_qty + ' 件' }}</template></el-table-column></el-table>
      <div class="ptw-inline-actions"><el-button v-if="action('prepare')" size="small" type="success" :disabled="locked" @click="prepare">建立本工序下料记录</el-button><el-button v-if="action('use_material')" size="small" type="success" plain icon="el-icon-plus" :disabled="locked" @click="openMaterials">选择实际已收原料</el-button></div>
      <template v-if="detail.operation_id">
        <h4>实际用料批次</h4><el-table :data="detail.batches.data" border size="mini" highlight-current-row :current-row-key="batch && batch.id" row-key="id" @row-click="chooseBatch"><el-table-column prop="batch_no" label="批次" min-width="160" /><el-table-column prop="item_name" label="原材料" min-width="115" /><el-table-column label="实际来源" min-width="120"><template slot-scope="{row}">{{ row.physical_no || ('数量 ' + row.input_qty) }}</template></el-table-column><el-table-column label="状态" width="100"><template slot-scope="{row}">{{ row.status === 'PROCESSING' ? '待核对结果' : row.status === 'CONFIRMED' ? '已确认' : '待核对状态' }}</template></el-table-column></el-table>
        <el-pagination class="ptw-pagination" small layout="total, prev, pager, next" :current-page="batchPage" :page-size="10" :total="detail.batches.meta.total" :disabled="busy || dirty" @current-change="changeBatchPage" />
      </template>
      <section v-if="batch" class="ptw-cutting-results">
        <h4>本批加工结果 · {{ batch.batch_no }}</h4>
        <template v-if="componentMode"><div v-for="row in components" :key="row.target_material_requirement_id" class="ptw-component-result"><div><strong>{{ row.raw_item_name }}</strong><small>{{ requirementText(row) }}</small><small>本批最多 {{ totalLength(row) ? totalLengthMetres(row.max_total_length_mm) + ' m' : row.max_piece_qty + ' 件' }}</small></div><el-input v-model="row.actualInput" size="small" :inputmode="totalLength(row) ? 'decimal' : 'numeric'" :disabled="locked || !action('save_results')" placeholder="填写实际合格数量" @input="resultsChanged"><span slot="append">{{ totalLength(row) ? 'm' : '件' }}</span></el-input></div></template>
        <div v-else class="ptw-form-row"><label>实际合格产出数量</label><el-input v-model="actualQty" size="small" inputmode="decimal" :disabled="locked || !action('save_results')" placeholder="填写实际完成数量" @input="resultsChanged" /></div>
        <div class="ptw-section-title"><h4>余料、废料和损耗</h4><el-button v-if="action('save_results')" size="mini" :disabled="locked" @click="addOther">添加实际结果</el-button></div>
        <section v-if="remnantRequired" class="ptw-remnant-review">
          <p class="ptw-muted">系统按本批实际投入和已保存产出计算余料建议。请按实际余料逐段或逐块填写，管材填长度，板材填面积。</p>
          <el-alert v-if="resultsDirty" title="实际产出或其他结果已变更，请先保存产出并更新余料建议，再核对确认。已填余料会保留。" type="warning" :closable="false" show-icon />
          <div v-for="source in remnantSources" :key="source.source_key" class="ptw-remnant-source">
            <div class="ptw-section-title"><strong>{{ source.source_label }}</strong><el-button v-if="action('save_results')" size="mini" :disabled="locked || resultsDirty || negativeSuggestion(source)" @click="adoptRemnantSuggestion(source)">采用系统建议</el-button></div>
            <p class="ptw-remnant-suggestion" :class="{'ptw-remnant-error': negativeSuggestion(source)}">系统建议余量：<strong>{{ remnantSuggestion(source) }}</strong> {{ remnantUnit(source) }}<span v-if="negativeSuggestion(source)">，实际结果已超过投入，请核对。</span></p>
            <p v-if="remnantReview.confirmed && remnantConfirmed && !dirty && source.confirmed_processing_consumption != null" class="ptw-muted">已确认加工耗用差额：{{ reviewConsumption(source) }} {{ remnantUnit(source) }}</p>
            <el-checkbox v-model="source.no_remnant" :disabled="locked || !action('save_results')" @change="remnantChanged">本来源没有可用余料</el-checkbox>
            <template v-if="!source.no_remnant">
              <div v-for="(row,index) in source.rows" :key="row.client_row_id" class="ptw-remnant-row">
                <label>{{ source.quantity_basis === 'area' ? '第' + (index + 1) + '块余料面积' : '第' + (index + 1) + '段余料长度' }}</label>
                <el-input v-model="row.amountInput" size="small" inputmode="decimal" :disabled="locked || !action('save_results')" :placeholder="source.quantity_basis === 'area' ? '填写实际面积，最多8位小数' : '填写实际长度，最多5位小数'" @input="remnantChanged"><span slot="append">{{ remnantUnit(source) }}</span></el-input>
                <el-button v-if="action('save_results')" size="mini" type="text" :disabled="locked" @click="removeRemnant(source,index)">移除</el-button>
              </div>
              <el-button v-if="action('save_results')" size="mini" plain :disabled="locked" @click="addRemnant(source)">{{ source.quantity_basis === 'area' ? '添加一块实际余料' : '添加一段实际余料' }}</el-button>
            </template>
          </div>
          <div class="ptw-remnant-confirmation">
            <el-checkbox v-model="remnantConfirmed" :disabled="locked || resultsDirty || !remnantsReady || !action('save_results')" @change="setDirty">已核对每段或每块可用余料；扣除已登记产出、报废和可用余料后的剩余部分按加工耗用计入本批成本</el-checkbox>
            <p v-if="remnantReview.confirmed && remnantConfirmed && !dirty" class="ptw-muted">已确认<template v-if="remnantReview.confirmed_by"> · {{ remnantReview.confirmed_by.label }}</template><template v-if="remnantReview.confirmed_at"> · {{ reviewTime(remnantReview.confirmed_at) }}</template></p>
            <p v-else class="ptw-muted">余料须保存确认后才能完成本工序；无可用余料不代表实测损耗为0。</p>
          </div>
        </section>
        <p v-if="!otherRows.length" class="ptw-muted">尚未登记其他结果。未登记的差额不代表实测损耗为0。</p>
        <div v-for="(row,index) in otherRows" :key="row.client_row_id" class="ptw-other-result"><div class="ptw-filters"><el-select v-model="row.result_type" size="small" :disabled="locked || !action('save_results')" @change="resultsChanged"><el-option v-if="!remnantRequired" label="可用余料" value="usable_remnant" /><el-option label="可回收废料" value="recyclable_scrap" /><el-option label="工艺损耗" value="process_loss" /><el-option label="报废产出" value="scrapped_output" /></el-select><el-select v-model="row.measurement_status" size="small" :disabled="locked || !action('save_results')" @change="measurementChanged(row)"><el-option label="已实测" value="MEASURED" /><el-option label="未测量" value="NOT_MEASURED" /><el-option label="未登记" value="NOT_RECORDED" /></el-select><el-button v-if="action('save_results')" size="mini" type="text" :disabled="locked" @click="removeOther(index)">移除</el-button></div><div v-if="row.measurement_status === 'MEASURED'" class="ptw-report-grid"><label>实际数量<el-input v-model="row.actual_qty" size="small" inputmode="decimal" :disabled="locked" @input="resultsChanged" /></label><label v-if="row.result_type === 'usable_remnant' && batch.physical_material_id">余料形状<el-select v-model="row.measurements.shape" size="small" :disabled="locked" @change="resultsChanged"><el-option label="矩形" value="RECTANGLE" /><el-option label="异形" value="IRREGULAR" /></el-select></label><label v-for="field in otherFields(row)" :key="field.key">{{ field.label }}<el-input v-model="row.measurements[field.key]" size="small" inputmode="decimal" :disabled="locked" @input="resultsChanged" /></label></div></div>
        <div class="ptw-inline-actions"><el-button v-if="action('save_results')" size="small" type="success" :loading="busy" :disabled="locked || !dirty" @click="save">{{ remnantRequired && resultsDirty ? '保存产出并更新余料建议' : '保存本批结果' }}</el-button><span v-if="dirty" class="ptw-muted">本批结果尚未保存</span></div>
      </section>
      <div v-if="action('finish')" class="ptw-cutting-finish"><p>请先保存每批实际结果；完成后将正式核对本工序全部加工用料和产出。</p><el-radio-group v-if="!componentMode && detail.target.output_mode_snapshot === 'warehouse_optional'" v-model="disposition" :disabled="locked"><el-radio label="direct_handover">直接交接</el-radio><el-radio label="warehouse">先入库</el-radio></el-radio-group><el-button size="small" type="success" :loading="busy" :disabled="locked || dirty || (remnantRequired && !remnantConfirmed)" @click="finish">确认下料并完成工序</el-button></div>
    </template>
    <el-dialog title="选择实际已收原料" :visible.sync="picker.visible" width="920px" custom-class="production-task-dialog" append-to-body :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy">
      <div class="ptw-material-picker"><aside><el-button type="text" @click="selectCategory(null)">全部分类</el-button><el-button v-for="row in picker.categories" :key="row.id" type="text" :class="{active:picker.categoryId===row.id}" @click="selectCategory(row.id)">{{ row.category_name }}</el-button><el-pagination small layout="prev, next" :current-page="picker.categoryPage" :page-size="10" :total="picker.categoryTotal" @current-change="loadCategories" /></aside><main><div class="ptw-filters"><el-input v-model.trim="picker.keyword" size="small" clearable prefix-icon="el-icon-search" placeholder="原材料名称、编码或规格" @keyup.enter.native="searchMaterials" /><el-button size="small" @click="searchMaterials">查询</el-button></div><el-alert v-if="picker.error" :title="picker.error" type="error" :closable="false" /><el-table :data="picker.rows" border size="small" v-loading="picker.loading"><el-table-column width="48"><template slot-scope="{row}"><el-radio :value="picker.selected && materialKey(picker.selected)" :label="materialKey(row)" :disabled="locked" @change="selectMaterial(row)"><span class="ptw-sr-only">选择{{ row.item_name }}</span></el-radio></template></el-table-column><el-table-column prop="item_name" label="原材料" min-width="120" /><el-table-column prop="spec" label="规格" min-width="105" /><el-table-column prop="batch_no" label="批次" min-width="135" /><el-table-column prop="physical_no" label="实物编号" min-width="135" /><el-table-column label="可用数量" min-width="105"><template slot-scope="{row}">{{ row.available_qty }} {{ row.stock_unit_name }}</template></el-table-column></el-table><el-pagination class="ptw-pagination" layout="total, prev, pager, next" :current-page="picker.page" :page-size="10" :total="picker.total" @current-change="loadMaterials" /><div v-if="picker.selected" class="ptw-selected-material"><strong>已选：{{ picker.selected.item_name }} · {{ picker.selected.physical_no || picker.selected.batch_no }}</strong><div v-if="!picker.selected.physical_material_id" class="ptw-form-row"><label>本次实际用料</label><el-input v-model="picker.quantity" size="small" inputmode="decimal" :disabled="locked" placeholder="填写实际库存数量"><span slot="append">{{ picker.selected.stock_unit_name }}</span></el-input></div><p v-else class="ptw-muted">按所选已收实物登记本次用料。</p></div></main></div>
      <span slot="footer"><el-button size="small" :disabled="busy" @click="picker.visible=false">取消</el-button><el-button size="small" type="success" :loading="busy" :disabled="!picker.selected || locked" @click="useMaterial">确认实际用料</el-button></span>
    </el-dialog>
  </section>
</template>

<script>
import { erpDateTime } from '@/utils/dateTime'
import { targetPath, getCuttingOperation, getCuttingMaterials, writeExecutionCommand, pendingExecutionCommands, retryExecutionCommand } from '@/api/erp/production-execution'
import { totalLengthMetres, totalLengthMillimetres, cuttingAreaSquareMetres, cuttingAreaSquareMillimetres } from '@/utils/cutting-quantity.mjs'

const object=value=>typeof value==='string'?JSON.parse(value):value||{}
const blankPicker=()=>({visible:false,keyword:'',categoryId:null,categories:[],categoryPage:1,categoryTotal:0,rows:[],page:1,total:0,selected:null,quantity:'',loading:false,error:'',sequence:0,categorySequence:0})
export default {
  name:'ProductionCuttingOperationPanel',props:{task:{type:Object,required:true},target:{type:Object,required:true},disabled:Boolean},
  data:()=>({detail:null,loading:false,busy:false,error:'',sequence:0,batchPage:1,batchId:null,components:[],otherRows:[],actualQty:'',dirty:false,resultsDirty:false,remnantSources:[],remnantConfirmed:false,pending:[],picker:blankPicker(),disposition:'direct_handover'}),
  computed:{base(){return targetPath(this.task.id,this.target)+'/cutting'},batch(){return this.detail?.current_batch || null},componentMode(){return this.detail?.output_kind==='cutting_components'},remnantReview(){return this.batch?.remnant_review || null},remnantRequired(){return this.remnantReview?.required===true},remnantsReady(){return !!this.remnantReview?.source_fingerprint&&this.remnantSources.length>0&&this.remnantSources.every(source=>['length','area'].includes(source.quantity_basis)&&this.remnantSuggestion(source)!=='待核对'&&!this.negativeSuggestion(source)&&(source.no_remnant||source.rows.length>0&&source.rows.every(row=>this.remnantMillimetres(source,row.amountInput)!==null&&Number(this.remnantMillimetres(source,row.amountInput))>0)))},locked(){return this.disabled||this.busy||this.loading||this.pending.length>0}},
  created(){this.pickerSequence=0;this.categorySequence=0;this.load()},beforeDestroy(){this.sequence++;this.pickerSequence++;this.categorySequence++},
  watch:{'target.business_version'(next,previous){if(next!==previous&&!this.busy&&!this.dirty)this.load()}},
  methods:{
    totalLengthMetres,totalLength(row){return row.quantity_basis==='total_length'},action(key){return !!this.detail?.allowed_actions?.[key]},materialKey(row){return `${row.production_input_holding_id}:${row.physical_material_id || ''}`},
    requirementText(row){if(this.totalLength(row))return `总用量 ${totalLengthMetres(row.required_total_length_mm)} m`;const d=row.dimensions||{};return `${[d.length_mm,d.width_mm,d.thickness_mm].filter(value=>value!=null).join(' × ')} mm · ${row.required_piece_qty} 件`},
    setDirty(){this.dirty=true;this.$emit('dirty',true)},refreshPending(){this.pending=pendingExecutionCommands(this.base)},
    resultsChanged(){this.resultsDirty=true;this.remnantConfirmed=false;this.setDirty()},
    reviewTime(value){return erpDateTime(value,19)},
    reviewConsumption(source){return source.quantity_basis==='area'?cuttingAreaSquareMetres(source.confirmed_processing_consumption):totalLengthMetres(source.confirmed_processing_consumption)},
    loadRemnantReview(review) {
      this.remnantConfirmed = review?.confirmed === true
      this.remnantSources = (review?.sources || []).map(source => ({ ...source, no_remnant: source.no_remnant === true, rows: (source.rows || []).map(row => ({ ...row, amountInput: source.quantity_basis === 'area' ? cuttingAreaSquareMetres(row.area_mm2) : totalLengthMetres(row.length_mm) })) }))
    },
    remnantUnit(source) { return source.quantity_basis === 'area' ? '㎡' : 'm' },
    remnantSuggestion(source) {
      const value = source.quantity_basis === 'area' ? source.suggested_area_mm2 : source.suggested_length_mm
      if (value == null || value === '') return '待核对'
      const text = String(value); const negative = text.startsWith('-'); const absolute = negative ? text.slice(1) : text
      const amount = source.quantity_basis === 'area' ? cuttingAreaSquareMetres(absolute) : totalLengthMetres(absolute)
      return amount === '' ? '待核对' : (negative ? '-' : '') + amount
    },
    negativeSuggestion(source) { return String(source.quantity_basis === 'area' ? source.suggested_area_mm2 : source.suggested_length_mm).startsWith('-') },
    remnantMillimetres(source, value) { return source.quantity_basis === 'area' ? cuttingAreaSquareMillimetres(value) : totalLengthMillimetres(value, 2) },
    remnantChanged() { this.remnantConfirmed=false; this.setDirty() },
    addRemnant(source) { if(this.locked)return; source.no_remnant=false; source.rows.push({client_row_id:`remnant-${Date.now()}-${Math.random().toString(16).slice(2)}`,amountInput:''}); this.remnantChanged() },
    removeRemnant(source,index) { if(this.locked)return; source.rows.splice(index,1); this.remnantChanged() },
    async adoptRemnantSuggestion(source) {
      if(this.locked||this.resultsDirty||this.negativeSuggestion(source))return
      const suggestion=this.remnantSuggestion(source)
      if(suggestion==='待核对')return this.$message.error('当前来源尚无有效余料建议，请先保存并核对实际结果')
      if(source.rows.length||source.no_remnant){try{await this.$confirm('采用系统建议将替换本来源已填写的余料，请核对实际分段或分块后再确认。','采用系统建议',{type:'warning'})}catch(_){return}}
      if(Number(suggestion)===0){source.no_remnant=true;source.rows=[]}else{source.no_remnant=false;source.rows=[{client_row_id:`remnant-${Date.now()}-${Math.random().toString(16).slice(2)}`,amountInput:suggestion}]}
      this.remnantChanged()
    },
    remnantPayload() {
      if(this.remnantConfirmed&&this.resultsDirty)throw new Error('请先保存实际产出并更新余料建议，再进行人工确认')
      const sources=this.remnantSources.map(source=>{
        if(!['length','area'].includes(source.quantity_basis))throw new Error('本批余料计量口径待核对，请刷新后确认')
        if(source.no_remnant)return {source_key:source.source_key,no_remnant:true,rows:[]}
        const rows=source.rows.filter(row=>this.remnantConfirmed||String(row.amountInput??'').trim()!=='').map(row=>{
          const amount=this.remnantMillimetres(source,row.amountInput)
          if(amount===null||Number(amount)<=0)throw new Error(source.quantity_basis==='area'?'请填写有效余料面积，平方米最多8位小数':'请填写有效余料长度，米最多5位小数')
          return {client_row_id:row.client_row_id,[source.quantity_basis==='area'?'area_mm2':'length_mm']:amount}
        })
        if(this.remnantConfirmed&&!rows.length)throw new Error('请逐段或逐块填写实际余料，或明确勾选本来源没有可用余料')
        return {source_key:source.source_key,no_remnant:false,rows}
      })
      return {confirmed:this.resultsDirty?false:this.remnantConfirmed,source_fingerprint:this.remnantReview.source_fingerprint,sources}
    },
    async load(){const sequence=++this.sequence;this.loading=true;this.error='';try{this.refreshPending();const response=await getCuttingOperation(this.task.id,this.target,{batch_page:this.batchPage,settlement_batch_id:this.batchId||undefined});if(sequence!==this.sequence)return;this.detail=response.data.data;const batch=this.batch;this.batchId=batch?.id||null;const results=this.detail.results||[];this.components=(batch?.component_requirements||[]).map(row=>{const saved=results.find(result=>result.result_type==='product'&&Number(object(result.cutting_requirement_snapshot).target_material_requirement_id)===Number(row.target_material_requirement_id));return {...row,actualInput:saved?(this.totalLength(row)?totalLengthMetres(object(saved.measurements).total_length_mm):String(saved.piece_qty).replace(/\.0+$/,'')):''}});const product=results.find(row=>row.result_type==='product');this.actualQty=product?String(product.actual_qty):'';this.loadRemnantReview(batch?.remnant_review);this.otherRows=results.filter(row=>row.result_type!=='product'&&(!this.remnantRequired||row.result_type!=='usable_remnant')).map(row=>({client_row_id:row.client_row_id,result_type:row.result_type,actual_qty:row.actual_qty==null?'':String(row.actual_qty),measurement_status:row.measurement_status,measurements:object(row.measurements)}));this.resultsDirty=false;this.disposition=this.detail.target.output_mode_snapshot==='warehouse_required'?'warehouse':'direct_handover';this.dirty=false;this.$emit('dirty',false)}catch(error){if(sequence===this.sequence)this.error=error.userMessage||error.message}finally{if(sequence===this.sequence)this.loading=false}},
    async canDiscard(){if(!this.dirty)return true;try{await this.$confirm('本批实际结果尚未保存，确认放弃这些未保存内容？','切换用料批次',{type:'warning'});return true}catch(_){return false}},
    async chooseBatch(row){if(this.locked||row.id===this.batchId||!await this.canDiscard())return;this.batchId=row.id;await this.load()},async changeBatchPage(page){if(this.locked||!await this.canDiscard())return;this.batchPage=page;this.batchId=null;await this.load()},
    async command(path,id,payload,method='POST'){if(this.busy)return false;this.busy=true;this.$emit('busy',true);this.error='';try{await writeExecutionCommand(method,path,id,payload,{task_id:this.task.id});this.$message.success('下料记录已保存');await this.load();this.$emit('updated');return true}catch(error){this.error=error.userMessage||error.message;this.refreshPending();this.$emit('updated');return false}finally{this.busy=false;this.$emit('busy',false)}},
    async recover(job){if(this.busy)return;this.busy=true;this.$emit('busy',true);try{await retryExecutionCommand(job);await this.load();this.$emit('updated');this.picker.visible=false;this.$message.success('原下料操作结果已确认')}catch(error){this.error=error.userMessage||error.message;this.refreshPending()}finally{this.busy=false;this.$emit('busy',false)}},
    prepare(){if(!this.locked&&this.action('prepare'))this.command(this.base+'/prepare',this.target.target_id,{expected_version:this.detail.target.business_version})},
    async openMaterials(){if(this.locked||!this.action('use_material')||!await this.canDiscard())return;this.picker=blankPicker();this.picker.visible=true;this.loadCategories(1);this.loadMaterials(1)},
    selectMaterial(row){if(this.locked)return;if(!this.picker.selected||this.materialKey(this.picker.selected)!==this.materialKey(row))this.picker.quantity='';this.picker.selected=row},
    selectCategory(id){if(this.locked)return;this.picker.categoryId=id;this.searchMaterials()},searchMaterials(){if(!this.locked)this.loadMaterials(1)},
    async loadCategories(page){const sequence=++this.categorySequence;try{const response=await getCuttingMaterials(this.task.id,this.target,{mode:'categories',page,per_page:10});if(sequence!==this.categorySequence||!this.picker.visible)return;this.picker.categories=response.data.data||[];this.picker.categoryPage=page;this.picker.categoryTotal=Number(response.data.meta?.total||0)}catch(error){if(sequence===this.categorySequence)this.picker.error=error.userMessage||error.message}},
    async loadMaterials(page){const sequence=++this.pickerSequence;this.picker.loading=true;this.picker.error='';try{const response=await getCuttingMaterials(this.task.id,this.target,{keyword:this.picker.keyword,category_id:this.picker.categoryId||undefined,page,per_page:10});if(sequence!==this.pickerSequence||!this.picker.visible)return;this.picker.rows=response.data.data||[];this.picker.page=page;this.picker.total=Number(response.data.meta?.total||0)}catch(error){if(sequence===this.pickerSequence)this.picker.error=error.userMessage||error.message}finally{if(sequence===this.pickerSequence)this.picker.loading=false}},
    async useMaterial(){const row=this.picker.selected;if(!row||this.locked||!this.action('use_material'))return;if(!row.physical_material_id&&(!/^\d+(?:\.\d{1,8})?$/.test(String(this.picker.quantity))||Number(this.picker.quantity)<=0||Number(this.picker.quantity)>Number(row.available_qty)))return this.$message.error('请填写本次实际已收原料的有效库存数量');const payload={expected_version:this.detail.target.business_version,production_input_holding_id:row.production_input_holding_id,...(row.physical_material_id?{physical_material_id:row.physical_material_id}:{quantity:this.picker.quantity})};if(await this.command(this.base+'/materials',this.target.target_id,payload))this.picker.visible=false},
    addOther(){if(this.locked)return;this.otherRows.push({client_row_id:`other-${Date.now()}-${Math.random().toString(16).slice(2)}`,result_type:this.remnantRequired?'recyclable_scrap':'usable_remnant',actual_qty:'',measurement_status:'NOT_RECORDED',measurements:{}});this.resultsChanged()},removeOther(index){if(this.locked)return;this.otherRows.splice(index,1);this.resultsChanged()},measurementChanged(row){if(row.measurement_status!=='MEASURED'){row.actual_qty='';row.measurements={}}this.resultsChanged()},
    otherFields(row){const fields=[];if(row.result_type==='usable_remnant'||row.result_type==='scrapped_output'){fields.push({key:'length_mm',label:'长度（mm）'});if(this.batch.physical_material_id)fields.push({key:'width_mm',label:'宽度（mm）'},{key:'thickness_mm',label:'厚度（mm）'})}if(row.result_type!=='usable_remnant'||row.measurements.shape==='IRREGULAR')fields.push({key:'weight_kg',label:'实测总重量（kg）'});return fields},
    async save(){if(this.locked||!this.batch||!this.action('save_results'))return;const payload={expected_version:this.batch.business_version};try{if(this.componentMode){payload.components=this.components.map(row=>{if(row.actualInput===''||row.actualInput==null)throw new Error('请逐条填写本批实际合格用量，无产出请明确填0');if(this.totalLength(row)){const value=totalLengthMillimetres(row.actualInput,5);if(value===null)throw new Error('实际总用量以米填写，最多八位小数');return {target_material_requirement_id:row.target_material_requirement_id,actual_total_length_mm:value}}if(!/^\d+$/.test(String(row.actualInput)))throw new Error('实际件数须为非负整数');return {target_material_requirement_id:row.target_material_requirement_id,actual_piece_qty:Number(row.actualInput)}})}else{if(!/^\d+(?:\.\d{1,8})?$/.test(String(this.actualQty)))throw new Error('请填写实际合格产出数量，无产出请明确填0');payload.actual_qty=this.actualQty}payload.other_results=this.otherRows.map(row=>{if(row.measurement_status!=='MEASURED')return {client_row_id:row.client_row_id,result_type:row.result_type,measurement_status:row.measurement_status};if(!/^\d+(?:\.\d{1,8})?$/.test(String(row.actual_qty)))throw new Error('已实测的其他结果须填写实际数量');const measurements={};for(const [key,value]of Object.entries(row.measurements)){if(value!==''&&value!=null)measurements[key]=value}return {client_row_id:row.client_row_id,result_type:row.result_type,measurement_status:'MEASURED',actual_qty:row.actual_qty,measurements}});if(this.remnantRequired)payload.remnant_review=this.remnantPayload()}catch(error){return this.$message.error(error.message)}await this.command(this.base+`/batches/${this.batch.id}`,this.batch.id,payload,'PUT')},
    async finish(){if(this.locked||this.dirty||(this.remnantRequired&&!this.remnantConfirmed)||!this.action('finish'))return;try{await this.$confirm('确认已保存本工序全部实际用料、加工结果和已实测其他结果？','确认下料并完成工序',{type:'warning'})}catch(_){return}await this.command(this.base+'/finish',this.target.target_id,{expected_version:this.detail.target.business_version,disposition:this.componentMode?'direct_handover':this.disposition})}
  }
}
</script>

